pub fn has_tiles() -> bool { !TILES.is_empty() }

pub fn tile_rgba(idx: u16) -> &'static [u8] {
    TILES[idx as usize]
}

pub fn tile_name(idx: u16) -> &'static str {
    TILE_NAMES[idx as usize]
}

